     1→# ABOUTME: Threaded interpreter for executing Sea of Nodes IR graphs
     2→# ABOUTME: Linearizes graph, executes nodes in topological order, returns result
     3→use 5.42.0;
     4→use experimental qw(class);
     5→use utf8;
     6→
     7→use Chalk::IR::Context;
     8→
     9→class Chalk::IR::Interpreter {
    10→    field $graph :param :reader;
    11→    field $context :reader;
    12→
    13→    ADJUST {
    14→        # Initialize context as empty closure
    15→        $context = Chalk::IR::Context->empty_context();
    16→    }
    17→
    18→    method execute() {
    19→        # 1. Linearize graph to get execution order
    20→        my @schedule = $graph->linearize();
    21→
    22→        # 2. Execute nodes in order using context threading
    23→        for my $node (@schedule) {
    24→            my $node_id = $node->id;
    25→            my $op = $node->op;
    26→
    27→            # Dispatch based on node execute() signature
    28→            # Different node types take different arguments
    29→            my %value_ops = (
    30→                Add => 1, Subtract => 1, Multiply => 1, Divide => 1,
    31→                GT => 1, LT => 1, EQ => 1, NE => 1, GE => 1, LE => 1,
    32→                Negate => 1, Not => 1, If => 1, Proj => 1, Region => 1, Phi => 1, Return => 1, Loop => 1, Reference => 1,
    33→                ArrayValue => 1, HashValue => 1,
    34→                ArrayGet => 1, ArraySet => 1, HashGet => 1, HashSet => 1,
    35→                ScalarDeref => 1, VariableRead => 1
    36→            );
    37→            my %simple_ops = ( Start => 1, Constant => 1 );
    38→
    39→            # Execute node with appropriate arguments
    40→            my $result;
    41→            if ($simple_ops{$op}) {
    42→                $result = $node->execute();
    43→            } elsif ($value_ops{$op}) {
    44→                $result = $node->execute($context);
    45→            } else {
    46→                die "Unknown op type: $op";
    47→            }
    48→
    49→            # Store result in context with node: namespace
    50→            $context = Chalk::IR::Context->extend_context($context, "node:$node_id", $result);
    51→        }
    52→
    53→        # 3. Find Return node and extract its value from context
    54→        my $return_node = $self->find_return();
    55→        return $context->("node:" . $return_node->id);
    56→    }
    57→
    58→    method find_return() {
    59→        # Find the Return node in the graph
    60→        # Prefer explicit return statements (with __CONTROL_PLACEHOLDER__) over implicit returns
    61→        # When multiple explicit returns exist (from parser intermediate states),
    62→        # choose the one with the highest node ID (most recently created)
    63→        my $nodes = $graph->nodes;
    64→
    65→        my @return_nodes;
    66→        # Parser compat: keys() requires parentheses around argument
    67→        my @node_ids = keys($nodes->%*);
    68→        for my $node_id (@node_ids) {
    69→            my $node = $nodes->{$node_id};
    70→            push @return_nodes, $node if $node->op eq 'Return';
    71→        }
    72→
    73→        die "No Return node found in graph" unless @return_nodes;
    74→
    75→        # If only one Return, use it
    76→        return $return_nodes[0] if @return_nodes == 1;
    77→
    78→        # Multiple Returns - prefer explicit return statements
    79→        # (those with __CONTROL_PLACEHOLDER__ as control input)
    80→        my @explicit_returns;
    81→        for my $node (@return_nodes) {
    82→            my @inputs = $node->inputs->@*;
    83→            if (@inputs > 0 && defined($inputs[0]) && $inputs[0] eq '__CONTROL_PLACEHOLDER__') {
    84→                push @explicit_returns, $node;
    85→            }
    86→        }
    87→
    88→        # If we found explicit returns, use the one with highest ID (most recent)
    89→        if (@explicit_returns) {
    90→            my $best = $explicit_returns[0];
    91→            for my $node (@explicit_returns) {
    92→                # Extract numeric part from node_N format
    93→                # node_42 -> 42 (skip first 5 chars: "node_")
    94→                my $node_id_str = $node->id;
    95→                my $best_id_str = $best->id;
    96→
    97→                my $id = substr($node_id_str, 5);
    98→                my $best_id = substr($best_id_str, 5);
    99→
   100→                $best = $node if $id > $best_id;
   101→            }
   102→            return $best;
   103→        }
   104→
   105→        # Multiple Return nodes but none are explicit - this indicates malformed IR
   106→        my @return_ids = map { $_->id } @return_nodes;
   107→        my $ids_str = join(', ', @return_ids);
   108→        die "Malformed IR graph: found multiple Return nodes ($ids_str) " .
   109→            "but none have __CONTROL_PLACEHOLDER__ control input. " .
   110→            "This indicates incorrect IR construction - each Return must be " .
   111→            "properly linked to control flow.";
   112→    }
   113→}
   114→
